            self.default_app = default_app
            self.create_app = create_app
            self.lock = Lock()
            self.instances = {}

def get_application(self, prefix):
            with self.lock:
                app = self.instances.get(prefix)
                if app is None:
                    app = self.create_app(prefix)
                    if app is not None:
                        self.instances[prefix] = app
                return app

